# 末事件 after 须与当前 ep_switch 预约严格一致：非空时摘要与触发时
# 刻逐值相等，空非状态互相对齐（无事件时预约必须不存在——从空状态
# 建立必然先有 SET 事件）。
if ep_switch_events:
    final_after = ep_switch_events[-1]["after"]
    if final_after is None:
        if ep_switch is not None:
            cp_state_int()
    else:
        if ep_switch is None or (
